import {it,expect} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {newId} from '../src/domain/model';
import {nativeDocuments,prepareNativeOperation} from '../src/sync/nativeBridge';
import {createSyncOperation} from '../src/sync/protocol';
import {bootstrapNativeProject,applyNativeOperation,type AtomicSyncRepository} from '../src/sync/server';
const root='/tmp/shinariokanri-independent-rb09-dd4328c/independent',actor={accountId:'00000000-0000-4000-8000-000000000001',sessionId:'10000000-0000-4000-8000-000000000001'},calls:unknown[]=[];
function arg(v:unknown){if(v===null)return'null';if(v&&typeof v==='object'&&'uuidArray'in v)return 'ARRAY['+(v as {uuidArray:string[]}).uuidArray.map(id=>{if(!/^[0-9a-f-]{36}$/.test(id))throw Error('INVALID_FIXTURE_UUID');return "'"+id+"'";}).join(',')+']::uuid[]';return"'"+(typeof v==='object'?JSON.stringify(v):String(v)).replace(/'/g,"''")+"'"+(typeof v==='object'?'::jsonb':'');}
function rpc(name:string,args:unknown[]){const sql='set role service_role;\nselect public.'+name+'('+args.map(arg).join(',')+')::text;\n',r=spawnSync('docker',['exec','-i','shinariokanri-independent-rb09-dd4328c','psql','-U','postgres','-qAt','-v','ON_ERROR_STOP=1'],{input:sql,encoding:'utf8',timeout:20000,maxBuffer:32*1024*1024});calls.push({name,args,status:r.status,stdout:r.stdout,stderr:r.stderr});writeFileSync(root+'/sql-native-typed-rpc-calls.json',JSON.stringify(calls,null,2)+'\n');if(r.status!==0)throw Error(r.stderr||'SQL_CALL_FAILED');return JSON.parse(r.stdout.trim());}
const repository:AtomicSyncRepository={read:async(identity,p,b,o)=>rpc('scenario_sync_engine_context',[identity.accountId,identity.sessionId,p,b,o]),bootstrap:async(identity,v)=>rpc('scenario_sync_bootstrap',[identity.accountId,identity.sessionId,v.project.projectId,v.project,v.documents,v.worlds]),commit:async(identity,v)=>rpc('scenario_sync_commit_prepared',[identity.accountId,identity.sessionId,v.projectId,v.expectedRevision,v.operation,v.operationHash,v.ack,v.documents,v.image,{uuidArray:v.derivedIds??[]}])};
function fixture(){const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')),pid=newId();f.p.projectId=pid;f.p.entities.forEach((e:any)=>e.projectId=pid);return f;}
function proof(id:string,value:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(value,null,2)+'\n');}
it('R9SQLV01 typed server→real isolated PostgreSQL bootstrap/apply/duplicate and unrelated remote changes use one confirmed image',async()=>{const f=fixture(),boot=await bootstrapNativeProject(repository,actor,{project:f.p,worlds:{}}),scope={accountId:actor.accountId,projectId:f.p.projectId},first=structuredClone(f.p);first.entities.find((e:any)=>e.id===f.idA).name='SQL端末Aの正常入力';const prepared=(await prepareNativeOperation(scope,boot,first,[],'SQL正常保存'))!,ack=await applyNativeOperation(repository,actor,prepared.operation);expect(ack.status).toBe('applied');expect(ack.serverRevision).toBe('2');expect(await applyNativeOperation(repository,actor,prepared.operation)).toEqual(ack);const second=structuredClone(f.p);second.entities.find((e:any)=>e.id===f.idB).name='SQL別対象Bの正常入力';const next=(await prepareNativeOperation(scope,boot,second,[],'SQL別対象'))!,secondAck=await applyNativeOperation(repository,actor,next.operation);expect(secondAck.serverRevision).toBe('3');const confirmed=await repository.read(actor,f.p.projectId,null,null);expect(confirmed.documents.find(d=>d.id===f.idA)?.fields.name).toBe('SQL端末Aの正常入力');expect(confirmed.documents.find(d=>d.id===f.idB)?.fields.name).toBe('SQL別対象Bの正常入力');proof('R9SQLV01',{boot,ack,secondAck,classification:'Actual Postgres17.11 network-none via typed server functions, mock auth/storage schemas; no real SupabaseAuth or API'});});
it('R9SQLV02 typed invalid target refuses whole atomic batch without PostgreSQL content/revision/operation side effects',async()=>{const f=fixture(),boot=await bootstrapNativeProject(repository,actor,{project:f.p,worlds:{}}),docs=nativeDocuments(f.p,'1'),a=structuredClone(docs.find(d=>d.id===f.idA)!),b=structuredClone(docs.find(d=>d.id===f.idB)!);a.fields.status='not-a-known-status';b.fields.name='他対象も拒否される';const operation=await createSyncOperation({scope:{accountId:actor.accountId,projectId:f.p.projectId},baseRevision:'1',operationId:newId(),targets:[{base:docs.find(d=>d.id===f.idA)!,local:a},{base:docs.find(d=>d.id===f.idB)!,local:b}]});await expect(applyNativeOperation(repository,actor,operation)).rejects.toMatchObject({code:'PROTOCOL_INVALID'});const after=await repository.read(actor,f.p.projectId,null,operation.operationId);expect(after.serverRevision).toBe('1');expect(after.documents).toEqual(boot.documents);expect(after.previousAck).toBe(null);proof('R9SQLV02',{operation,after,refusedAtomically:true});});
it('R9SQLV03 deletion-vs-edit refuses all targets and a partial resolution is rejected by locked DB operation without losing old evidence',async()=>{const f=fixture(),boot=await bootstrapNativeProject(repository,actor,{project:f.p,worlds:{}}),scope={accountId:actor.accountId,projectId:f.p.projectId},deleted=structuredClone(f.p),a=deleted.entities.find((e:any)=>e.id===f.idA);a.deletedAt='2026-10-08T00:00:00.000Z';a.deletionOperationId=newId();const removal=(await prepareNativeOperation(scope,boot,deleted,[],'削除'))!;await applyNativeOperation(repository,actor,removal.operation);const edited=structuredClone(f.p);edited.entities.find((e:any)=>e.id===f.idA).name='削除と競合する編集';edited.entities.find((e:any)=>e.id===f.idB).name='一括拒否される別対象';const pending=(await prepareNativeOperation(scope,boot,edited,[],'削除対編集'))!,conflicted=await applyNativeOperation(repository,actor,pending.operation);expect(conflicted.status).toBe('conflict');expect(conflicted.conflicts.some(c=>c.reasons.includes('delete-versus-edit'))).toBe(true);expect(conflicted.confirmedDocuments!.find(d=>d.id===f.idB)?.fields.name).toBe('共通B');const state=await repository.read(actor,f.p.projectId,conflicted.serverRevision,pending.operation.operationId),local=structuredClone(state.documents.find(d=>d.id===f.idA)!);local.tombstone=null;local.fields.name='不完全な解決';const incomplete=await createSyncOperation({scope,baseRevision:state.serverRevision,operationId:newId(),targets:[{base:state.documents.find(d=>d.id===f.idA)!,local}],resolvesOperationId:pending.operation.operationId});await expect(applyNativeOperation(repository,actor,incomplete)).rejects.toThrow('RESOLUTION_INCOMPLETE');const after=await repository.read(actor,f.p.projectId,null,pending.operation.operationId);expect(after.documents).toEqual(state.documents);expect(after.serverRevision).toBe(state.serverRevision);expect(after.previousAck).toEqual(conflicted);proof('R9SQLV03',{conflicted,incomplete,after,refusedAtomically:true});});

it('R9SQLV04 membership revocation between typed read and DB locked commit rejects the whole operation without content/history/ack effects',async()=>{
 const f=fixture(),boot=await bootstrapNativeProject(repository,actor,{project:f.p,worlds:{}}),next=structuredClone(f.p);next.entities.find((e:any)=>e.id===f.idA).name='権限撤回後には保存しない';
 const prepared=(await prepareNativeOperation({accountId:actor.accountId,projectId:f.p.projectId},boot,next,[],'revoke before locked commit'))!;
 function admin(sql:string){const r=spawnSync('docker',['exec','-i','shinariokanri-independent-rb09-dd4328c','psql','-U','postgres','-qAt','-v','ON_ERROR_STOP=1'],{input:sql,encoding:'utf8',timeout:20000});if(r.status!==0)throw Error(r.stderr);return r.stdout;}
 const revoking:AtomicSyncRepository={...repository,commit:async(identity,value)=>{admin("update scenario_private.memberships set revoked_at=now() where project_id='"+f.p.projectId+"' and account_id='"+actor.accountId+"';");return repository.commit(identity,value);}};
 await expect(applyNativeOperation(revoking,actor,prepared.operation)).rejects.toThrow('FORBIDDEN');
 const raw=admin("select json_build_object('revision',revision,'operationCount',(select count(*) from scenario_private.operations where project_id='"+f.p.projectId+"'))::text from scenario_private.projects where id='"+f.p.projectId+"';");const observation=JSON.parse(raw.trim());expect(observation).toEqual({revision:1,operationCount:0});
 admin("update scenario_private.memberships set revoked_at=null where project_id='"+f.p.projectId+"' and account_id='"+actor.accountId+"';");const after=await repository.read(actor,f.p.projectId,null,prepared.operationId);expect(after.documents).toEqual(boot.documents);expect(after.previousAck).toBe(null);
 proof('R9SQLV04',{operation:prepared.operation,observation,after,classification:'Real isolated PostgreSQL locked commit with synthetic role/session records; not real Auth/API'});
});
